from __future__ import annotations

import csv
import copy
import json
import os
import re
import shutil
import sys
import zipfile
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple
import xml.etree.ElementTree as ET


HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."


@dataclass
class UpdateData:
    customer: str
    owner_name: str
    window_start: str
    window_end: str
    band: str
    escalation_email: str
    note: str


def read_update_json(path: str) -> UpdateData:
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)
    return UpdateData(
        customer=raw["customer"],
        owner_name=raw["owner_name"],
        window_start=raw["window_start"],
        window_end=raw["window_end"],
        band=raw["band"],
        escalation_email=raw["escalation_email"],
        note=raw["note"],
    )


def read_followups_csv(path: str) -> List[Tuple[int, str]]:
    items: List[Tuple[int, str]] = []
    with open(path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            seq = int(row["sequence"].strip())
            item = (row["item"] or "").strip()
            items.append((seq, item))
    items.sort(key=lambda x: x[0])
    return items


def collect_namespaces(xml_path: str) -> Dict[str, str]:
    ns: Dict[str, str] = {}
    for event, elem in ET.iterparse(xml_path, events=("start-ns",)):
        prefix, uri = elem
        # ElementTree uses '' for default namespace
        if prefix in ns and ns[prefix] == uri:
            continue
        ns[prefix] = uri
    return ns


def register_namespaces(nsmap: Dict[str, str]) -> None:
    # Avoid ns0/ns1 prefix pollution when writing
    for prefix, uri in nsmap.items():
        ET.register_namespace(prefix, uri)


def hp_ns(nsmap: Dict[str, str]) -> Dict[str, str]:
    # Prefer the existing 'hp' prefix if present; else fall back to the known HWPML ns.
    if "hp" in nsmap:
        return {"hp": nsmap["hp"]}
