    first_t.text = new_text

    # Remove other <hp:t> nodes.
    all_ts = p.findall(".//hp:t", ns)
    for t in all_ts[1:]:
        parent = None
        # ElementTree has no getparent(); find by scanning runs
        for run in p.findall(".//hp:run", ns):
            for child in list(run):
                if child is t:
                    parent = run
                    break
            if parent is not None:
                break
        if parent is not None:
            parent.remove(t)

    # Remove empty runs (runs with no children)
    for run in list(p.findall(".//hp:run", ns)):
        if len(list(run)) == 0:
