        # Customer line
        if "고객사:" in new_full:
            new_full = re.sub(r"(고객사:\s*).*$", r"\\1" + data.customer, new_full)

        # Owner line
        if "현 담당자:" in new_full:
            new_full = re.sub(r"(현 담당자:\s*).*$", r"\\1" + data.owner_name, new_full)

        # Renewal window lines (appears in multiple sections)
        if "갱신 윈도우:" in new_full:
            new_full = re.sub(r"(갱신 윈도우:\s*).*$", r"\\1" + window, new_full)
        if "갱신 윈도우 확인:" in new_full:
            new_full = re.sub(r"(갱신 윈도우 확인:\s*).*$", r"\\1" + window, new_full)

        # Pricing band cell (table value only)
        if new_full.strip() == "Standard-18M":
            new_full = data.band

        # Escalation contact cell (email)
        stripped = new_full.strip()
        if re.fullmatch(r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+", stripped) and "northwind" in stripped:
            new_full = data.escalation_email

        # Pricing note line
        if new_full.startswith("가격 메모:"):
            new_full = re.sub(r"(가격 메모:\s*).*$", r"\\1" + data.note, new_full)
        # In case note text appears without the label
        if "기존 메모를 새 메모로 바꾸세요." in new_full:
            new_full = new_full.replace("기존 메모를 새 메모로 바꾸세요.", data.note)

        if new_full != full:
            if set_paragraph_text(p, ns, new_full):
                changed += 1

    return changed


def max_paragraph_id(root: ET.Element, ns: Dict[str, str]) -> int:
    max_id = 0
    for p in root.findall(".//hp:p", ns):
        pid = p.get("id")
        if pid is None:
            continue
        try:
            max_id = max(max_id, int(pid))
        except ValueError:
            continue
    return max_id


def update_followups_in_section(root: ET.Element, ns: Dict[str, str], followups: List[Tuple[int, str]]) -> int:
    """Replace the numbered follow-up paragraphs under the '후속 조치' heading.

    Returns number of paragraphs whose text was modified or inserted.
    """

    # Only handle the common pattern where followups live as direct children
    # of the section element.
    children = list(root)

    def child_text(elem: ET.Element) -> str:
        if elem.tag != f"{{{ns['hp']}}}p":
            return ""
        return concat_paragraph_text(elem, ns)

    heading_idx: Optional[int] = None
    for i, ch in enumerate(children):
        if ch.tag == f"{{{ns['hp']}}}p" and child_text(ch).strip() == "후속 조치":
            heading_idx = i
            break

    if heading_idx is None:
        return 0

    # Collect existing numbered follow-up lines after the heading
    existing: List[ET.Element] = []
    for ch in children[heading_idx + 1 :]:
        if ch.tag != f"{{{ns['hp']}}}p":
            # Stop once a non-paragraph element begins
            break
        txt = child_text(ch).strip()
        if re.match(r"^\d+\.\s+", txt):
            existing.append(ch)
            continue
        # Stop once we leave the numbered list
        if existing:
            break

    # If nothing found, don't guess.
    if not existing:
        return 0

    desired_lines = [f"{seq}. {item}" for seq, item in followups]

    changed = 0

    # Update existing paragraphs
    for i, p in enumerate(existing):
        if i >= len(desired_lines):
            break
        if set_paragraph_text(p, ns, desired_lines[i]):
            changed += 1

    # Remove extra existing paragraphs (if CSV has fewer lines)
    if len(existing) > len(desired_lines):
        for p in existing[len(desired_lines) :]:
            # Ensure we are removing a direct child
            if p in list(root):
                root.remove(p)
                changed += 1

    # Insert additional paragraphs (if CSV has more lines)
    if len(desired_lines) > len(existing):
        next_id = max_paragraph_id(root, ns) + 1
        template = existing[-1]
        insert_after = existing[-1]
        insert_pos = list(root).index(insert_after) + 1

        for line in desired_lines[len(existing) :]:
            new_p = copy.deepcopy(template)
            new_p.set("id", str(next_id))
            next_id += 1

            set_paragraph_text(new_p, ns, line)
            # Defensive: ensure layout cache removed
            remove_linesegarray(new_p, ns)

            root.insert(insert_pos, new_p)
            insert_pos += 1
            changed += 1

    return changed


def ensure_appendix_preserved(root: ET.Element, ns: Dict[str, str]) -> None:
    found = False
    for p in root.findall(".//hp:p", ns):
        if concat_paragraph_text(p, ns) == APPENDIX_SENTENCE:
            found = True
            break
    if not found:
        raise RuntimeError("Appendix sentence is missing after update")


def update_section_xml(xml_path: str, data: UpdateData, followups: List[Tuple[int, str]]) -> Dict[str, int]:
    nsmap = collect_namespaces(xml_path)
    register_namespaces(nsmap)
    ns = hp_ns(nsmap)

    tree = ET.parse(xml_path)
