def find_inputs() -> Tuple[str, str, str]:
    # Inputs are expected in /root but we allow searching nearby task dirs.
    candidates = ["/root", os.getcwd()]
    extra_dirs = []
    for base in ["/root", os.getcwd()]:
        for name in ["task", "data", "inputs"]:
