#!/usr/bin/env python3
"""Update renewal_playbook.hwpx using renewal_update.json and followups.csv.

Produces: /root/renewal_playbook_updated.hwpx

Notes:
- HWPX is a ZIP container; HWPX text is often fragmented across multiple <hp:t> nodes.
- For any paragraph whose text is modified, we:
  * remove <hp:linesegarray> children (layout cache) to avoid overlapping glyphs
  * collapse all <hp:t> nodes into a single <hp:t>
- Output ZIP requirements:
  * First entry must be 'mimetype'
  * 'mimetype' must be uncompressed (ZIP_STORED)
"""

from __future__ import annotations

import csv
import copy
import json
import os
import re
import shutil
import sys
import zipfile
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple
import xml.etree.ElementTree as ET


HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
APPENDIX_SENTENCE = "이 부록 문단은 그대로 유지해야 합니다."


@dataclass
class UpdateData:
    customer: str
    owner_name: str
    window_start: str
    window_end: str
    band: str
    escalation_email: str
    note: str


def read_update_json(path: str) -> UpdateData:
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)
    return UpdateData(
        customer=raw["customer"],
        owner_name=raw["owner_name"],
        window_start=raw["window_start"],
        window_end=raw["window_end"],
        band=raw["band"],
        escalation_email=raw["escalation_email"],
        note=raw["note"],
    )


def read_followups_csv(path: str) -> List[Tuple[int, str]]:
    items: List[Tuple[int, str]] = []
    with open(path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            seq = int(row["sequence"].strip())
            item = (row["item"] or "").strip()
            items.append((seq, item))
    items.sort(key=lambda x: x[0])
    return items


def collect_namespaces(xml_path: str) -> Dict[str, str]:
    ns: Dict[str, str] = {}
    for event, elem in ET.iterparse(xml_path, events=("start-ns",)):
        prefix, uri = elem
        # ElementTree uses '' for default namespace
        if prefix in ns and ns[prefix] == uri:
            continue
        ns[prefix] = uri
    return ns


def register_namespaces(nsmap: Dict[str, str]) -> None:
    # Avoid ns0/ns1 prefix pollution when writing
    for prefix, uri in nsmap.items():
        ET.register_namespace(prefix, uri)


def hp_ns(nsmap: Dict[str, str]) -> Dict[str, str]:
    # Prefer the existing 'hp' prefix if present; else fall back to the known HWPML ns.
    if "hp" in nsmap:
        return {"hp": nsmap["hp"]}
    # Sometimes the file could define a default namespace only.
    for pfx, uri in nsmap.items():
        if uri == HWPML_NS:
            return {"hp": uri}
    return {"hp": HWPML_NS}


def concat_paragraph_text(p: ET.Element, ns: Dict[str, str]) -> str:
    parts: List[str] = []
    for t in p.findall(".//hp:t", ns):
        parts.append(t.text or "")
    return "".join(parts)


def _ensure_run_and_t(p: ET.Element, ns: Dict[str, str]) -> Tuple[ET.Element, ET.Element]:
    run = p.find("hp:run", ns)
    if run is None:
        run = ET.SubElement(p, f"{{{ns['hp']}}}run")
        run.set("charPrIDRef", "0")
    t = run.find("hp:t", ns)
    if t is None:
        t = ET.SubElement(run, f"{{{ns['hp']}}}t")
    return run, t


def remove_linesegarray(p: ET.Element, ns: Dict[str, str]) -> None:
    # <hp:linesegarray> is usually a direct child of <hp:p>
    for lsa in list(p.findall("hp:linesegarray", ns)):
        p.remove(lsa)


def collapse_text_nodes(p: ET.Element, ns: Dict[str, str], new_text: str) -> None:
    # Put all paragraph text into the first <hp:t>, remove all other <hp:t>.
    _, first_t = _ensure_run_and_t(p, ns)
    first_t.text = new_text

    # Remove other <hp:t> nodes.
    all_ts = p.findall(".//hp:t", ns)
    for t in all_ts[1:]:
        parent = None
        # ElementTree has no getparent(); find by scanning runs
        for run in p.findall(".//hp:run", ns):
            for child in list(run):
                if child is t:
                    parent = run
                    break
            if parent is not None:
                break
        if parent is not None:
            parent.remove(t)

    # Remove empty runs (runs with no children)
    for run in list(p.findall(".//hp:run", ns)):
        if len(list(run)) == 0:
            # Only remove if it's a direct child of p or nested in a stable way.
            # In this simplified task document, runs are direct children of p.
            if run in list(p):
                p.remove(run)


def set_paragraph_text(p: ET.Element, ns: Dict[str, str], new_text: str) -> bool:
    old_text = concat_paragraph_text(p, ns)
    if old_text == new_text:
        return False

    collapse_text_nodes(p, ns, new_text)
    remove_linesegarray(p, ns)
    return True


def update_field_paragraphs(root: ET.Element, ns: Dict[str, str], data: UpdateData) -> int:
    changed = 0
    window = f"{data.window_start} ~ {data.window_end}"

    for p in root.findall(".//hp:p", ns):
        full = concat_paragraph_text(p, ns)

        if full == APPENDIX_SENTENCE:
            # Must never change
            continue

        new_full = full

        # Customer line
        if "고객사:" in new_full:
            new_full = re.sub(r"(고객사:\s*).*$", r"\\1" + data.customer, new_full)

        # Owner line
        if "현 담당자:" in new_full:
            new_full = re.sub(r"(현 담당자:\s*).*$", r"\\1" + data.owner_name, new_full)

        # Renewal window lines (appears in multiple sections)
        if "갱신 윈도우:" in new_full:
            new_full = re.sub(r"(갱신 윈도우:\s*).*$", r"\\1" + window, new_full)
        if "갱신 윈도우 확인:" in new_full:
            new_full = re.sub(r"(갱신 윈도우 확인:\s*).*$", r"\\1" + window, new_full)

        # Pricing band cell (table value only)
        if new_full.strip() == "Standard-18M":
            new_full = data.band

        # Escalation contact cell (email)
        stripped = new_full.strip()
        if re.fullmatch(r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+", stripped) and "northwind" in stripped:
            new_full = data.escalation_email

        # Pricing note line
        if new_full.startswith("가격 메모:"):
            new_full = re.sub(r"(가격 메모:\s*).*$", r"\\1" + data.note, new_full)
        # In case note text appears without the label
        if "기존 메모를 새 메모로 바꾸세요." in new_full:
            new_full = new_full.replace("기존 메모를 새 메모로 바꾸세요.", data.note)

        if new_full != full:
            if set_paragraph_text(p, ns, new_full):
                changed += 1

    return changed


def max_paragraph_id(root: ET.Element, ns: Dict[str, str]) -> int:
    max_id = 0
    for p in root.findall(".//hp:p", ns):
        pid = p.get("id")
        if pid is None:
            continue
        try:
            max_id = max(max_id, int(pid))
        except ValueError:
            continue
    return max_id


def update_followups_in_section(root: ET.Element, ns: Dict[str, str], followups: List[Tuple[int, str]]) -> int:
    """Replace the numbered follow-up paragraphs under the '후속 조치' heading.

    Returns number of paragraphs whose text was modified or inserted.
    """

    # Only handle the common pattern where followups live as direct children
    # of the section element.
    children = list(root)

    def child_text(elem: ET.Element) -> str:
        if elem.tag != f"{{{ns['hp']}}}p":
            return ""
        return concat_paragraph_text(elem, ns)

    heading_idx: Optional[int] = None
    for i, ch in enumerate(children):
        if ch.tag == f"{{{ns['hp']}}}p" and child_text(ch).strip() == "후속 조치":
            heading_idx = i
            break

    if heading_idx is None:
        return 0

    # Collect existing numbered follow-up lines after the heading
    existing: List[ET.Element] = []
    for ch in children[heading_idx + 1 :]:
        if ch.tag != f"{{{ns['hp']}}}p":
            # Stop once a non-paragraph element begins
            break
        txt = child_text(ch).strip()
        if re.match(r"^\d+\.\s+", txt):
            existing.append(ch)
            continue
        # Stop once we leave the numbered list
        if existing:
            break

    # If nothing found, don't guess.
    if not existing:
        return 0

    desired_lines = [f"{seq}. {item}" for seq, item in followups]

    changed = 0

    # Update existing paragraphs
    for i, p in enumerate(existing):
        if i >= len(desired_lines):
            break
        if set_paragraph_text(p, ns, desired_lines[i]):
            changed += 1

    # Remove extra existing paragraphs (if CSV has fewer lines)
    if len(existing) > len(desired_lines):
        for p in existing[len(desired_lines) :]:
            # Ensure we are removing a direct child
            if p in list(root):
                root.remove(p)
                changed += 1

    # Insert additional paragraphs (if CSV has more lines)
    if len(desired_lines) > len(existing):
        next_id = max_paragraph_id(root, ns) + 1
        template = existing[-1]
        insert_after = existing[-1]
        insert_pos = list(root).index(insert_after) + 1

        for line in desired_lines[len(existing) :]:
            new_p = copy.deepcopy(template)
            new_p.set("id", str(next_id))
            next_id += 1

            set_paragraph_text(new_p, ns, line)
            # Defensive: ensure layout cache removed
            remove_linesegarray(new_p, ns)

            root.insert(insert_pos, new_p)
            insert_pos += 1
            changed += 1

    return changed


def ensure_appendix_preserved(root: ET.Element, ns: Dict[str, str]) -> None:
    found = False
    for p in root.findall(".//hp:p", ns):
        if concat_paragraph_text(p, ns) == APPENDIX_SENTENCE:
            found = True
            break
    if not found:
        raise RuntimeError("Appendix sentence is missing after update")


def update_section_xml(xml_path: str, data: UpdateData, followups: List[Tuple[int, str]]) -> Dict[str, int]:
    nsmap = collect_namespaces(xml_path)
    register_namespaces(nsmap)
    ns = hp_ns(nsmap)

    tree = ET.parse(xml_path)
    root = tree.getroot()

    changed_fields = update_field_paragraphs(root, ns, data)
    changed_followups = update_followups_in_section(root, ns, followups)
    ensure_appendix_preserved(root, ns)

    tree.write(xml_path, encoding="UTF-8", xml_declaration=True)
    return {"fields": changed_fields, "followups": changed_followups}


def find_inputs() -> Tuple[str, str, str]:
    # Inputs are expected in /root but we allow searching nearby task dirs.
    candidates = ["/root", os.getcwd()]
    extra_dirs = []
    for base in ["/root", os.getcwd()]:
        for name in ["task", "data", "inputs"]:
            extra_dirs.append(os.path.join(base, name))
    candidates.extend(extra_dirs)

    def find_one(filename: str) -> str:
        for d in candidates:
            p = os.path.join(d, filename)
            if os.path.isfile(p):
                return p
        raise FileNotFoundError(f"Could not find {filename} in {candidates}")

    hwpx = find_one("renewal_playbook.hwpx")
    upd = find_one("renewal_update.json")
    csvp = find_one("followups.csv")
    return hwpx, upd, csvp


def extract_hwpx(src_hwpx: str, work_dir: str) -> List[zipfile.ZipInfo]:
    if os.path.exists(work_dir):
        shutil.rmtree(work_dir)
    os.makedirs(work_dir, exist_ok=True)

    with zipfile.ZipFile(src_hwpx, "r") as z:
        infos = z.infolist()
        z.extractall(work_dir)
        return infos


def repack_hwpx(
    out_hwpx: str,
    work_dir: str,
    original_infos: List[zipfile.ZipInfo],
    mimetype_value: bytes,
) -> None:
    if os.path.exists(out_hwpx):
        os.remove(out_hwpx)

    # Maintain original order for existing entries.
    original_names = [i.filename for i in original_infos]

    with zipfile.ZipFile(out_hwpx, "w") as z:
        # 1) mimetype first, stored
        zi = zipfile.ZipInfo("mimetype")
        zi.compress_type = zipfile.ZIP_STORED
        zi.extra = b""
        # Use a stable timestamp
        zi.date_time = (2020, 1, 1, 0, 0, 0)
        z.writestr(zi, mimetype_value)

        # 2) write all original entries (modified ones already updated on disk)
        for name in original_names:
            src_path = os.path.join(work_dir, name)
            if not os.path.isfile(src_path):
                raise FileNotFoundError(f"Missing extracted entry: {name}")

            with open(src_path, "rb") as f:
                data = f.read()

            # Preserve timestamps when possible
            orig = next((i for i in original_infos if i.filename == name), None)
            zi2 = zipfile.ZipInfo(name)
            zi2.compress_type = zipfile.ZIP_DEFLATED
            zi2.extra = b""
            if orig is not None:
                zi2.date_time = orig.date_time

            z.writestr(zi2, data)


def main() -> int:
    src_hwpx, upd_json, follow_csv = find_inputs()
    data = read_update_json(upd_json)
    followups = read_followups_csv(follow_csv)

    work_dir = "/tmp/hwpx_work"
    original_infos = extract_hwpx(src_hwpx, work_dir)

    # Update each section xml listed in the container
    sections = []
    for info in original_infos:
        if re.match(r"^Contents/section\d+\.xml$", info.filename):
            sections.append(info.filename)

    if not sections:
        raise RuntimeError("No section XML files found in HWPX")

    stats = {}
    for sec in sections:
        path = os.path.join(work_dir, sec)
        stats[sec] = update_section_xml(path, data, followups)

    # HWPX 'mimetype' value used inside the package.
    # Keep this exact (no trailing newline) for verifier friendliness.
    mimetype_value = b"application/hwp+zip"

    out_hwpx = "/root/renewal_playbook_updated.hwpx"
    repack_hwpx(out_hwpx, work_dir, original_infos, mimetype_value)

    print("Updated:", out_hwpx)
    print("Section update stats:")
    for k in sorted(stats.keys()):
        print(f"- {k}: {stats[k]}")

    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print("ERROR:", str(e), file=sys.stderr)
        raise

